/**
 * Imports a planting-estimates workbook (exported as three UTF-8 CSV sheets)
 * into src/data/crop-estimates.ts, and writes an Arabic import report.
 *
 * Run:   npm run estimates:import
 * Check: npm run estimates:check   (fails when the generated file is stale)
 *
 * Options (all optional):
 *   --main <csv> --regions <csv> --extra <csv>   input sheets
 *   --dataset <id>                              dataset id stored with every estimate
 *   --out <ts> --report <md>                    output paths
 *   --check                                     compare instead of writing
 *
 * The input is validated row by row (see scripts/estimates/import-core.ts).
 * Structural errors (missing columns, unknown crops, names that do not match
 * the catalogue) stop the import. Bad values are excluded and listed in the
 * report with their reason; nothing is guessed or silently fixed.
 */
import { readFileSync, writeFileSync } from "node:fs";
import { join } from "node:path";
import { CATALOGUE_BASE } from "../src/data/crop-catalogue";
import { CLIMATE_ZONE_LABELS } from "../src/domain/labels";
import { parseCsv } from "./estimates/csv";
import { importEstimates, type ImportIssue, type ImportResult } from "./estimates/import-core";
import { REVIEW_NOTES } from "./estimates/review-notes";

function arg(name: string, fallback: string): string {
  const i = process.argv.indexOf(`--${name}`);
  return i > 0 && process.argv[i + 1] ? process.argv[i + 1] : fallback;
}

const root = process.cwd();
const paths = {
  main: arg("main", "data/imports/smartplant_88_main.csv"),
  regions: arg("regions", "data/imports/smartplant_88_regions.csv"),
  extra: arg("extra", "data/imports/smartplant_88_extra_seasons.csv"),
  out: arg("out", "src/data/crop-estimates.ts"),
  report: arg("report", "data/imports/IMPORT_REPORT.md"),
};
const dataset = arg("dataset", "smartplant-88-ps");
const check = process.argv.includes("--check");

const read = (p: string) => parseCsv(readFileSync(join(root, p), "utf8"));
const result = importEstimates({
  main: read(paths.main),
  regions: read(paths.regions),
  extra: read(paths.extra),
  catalogue: CATALOGUE_BASE,
  dataset,
});

const errors = result.issues.filter((i) => i.level === "error");
if (errors.length) {
  for (const e of errors) console.error(`خطأ [${e.file}${e.line ? `:${e.line}` : ""}] ${e.slug ?? ""}: ${e.message}`);
  console.error(`توقف الاستيراد: ${errors.length} خطأ بنيوي.`);
  process.exit(1);
}

function moduleSource(r: ImportResult): string {
  const lines = [
    "// Generated by scripts/import-estimates.ts — do not edit by hand.",
    `// Source: ${paths.main}, ${paths.regions}, ${paths.extra}`,
    "// ESTIMATES ONLY: not documented, not reviewed. Documented windows always take precedence.",
    'import type { CropEstimateData } from "@/domain/types";',
    "",
    `export const ESTIMATE_DATASET = ${JSON.stringify({ id: dataset, crops: r.stats.crops, plantingWindows: r.stats.plantingWindows, optionalWindows: r.stats.optionalWindows })} as const;`,
    "",
    "export const CROP_ESTIMATES: Record<string, CropEstimateData> = {",
  ];
  for (const c of r.crops) {
    const { slug, name, ...data } = c;
    void name;
    lines.push(`  ${JSON.stringify(slug)}: ${JSON.stringify(data)},`);
  }
  lines.push("};", "");
  return lines.join("\n");
}

const zoneName = (i: ImportIssue) => (i.zone ? CLIMATE_ZONE_LABELS[i.zone] : "—");
const fileName: Record<ImportIssue["file"], string> = { main: "الأساسي", regions: "المناطق", extra: "العروات الإضافية" };
const esc = (s: string) => s.replace(/\|/g, "\\|");

function reportSource(r: ImportResult): string {
  const excluded = r.issues.filter((i) => i.level === "excluded");
  const warnings = r.issues.filter((i) => i.level === "warning");
  const names = new Map(CATALOGUE_BASE.map((c) => [c.slug, c.name]));
  const row = (i: ImportIssue) =>
    `| ${fileName[i.file]}${i.line ? ` (سطر ${i.line})` : ""} | ${i.slug ? `${names.get(i.slug) ?? i.slug} (\`${i.slug}\`)` : "—"} | ${zoneName(i)} | ${i.what ? `${esc(i.what)}: ` : ""}${esc(i.message)} |`;
  const out = [
    "# تقرير استيراد المواعيد التقديرية",
    "",
    "> مولَّد آليًا بواسطة `npm run estimates:import`. لا تعدّله يدويًا.",
    "",
    `- مجموعة البيانات: \`${dataset}\``,
    `- الملفات: \`${paths.main}\`، \`${paths.regions}\`، \`${paths.extra}\``,
    "",
    "## الأرقام",
    "",
    "| البند | العدد |",
    "| --- | --- |",
    `| صفوف الورقة الأساسية (مرتفعات) | ${r.stats.mainRows} |`,
    `| صفوف المناطق الإضافية | ${r.stats.regionRows} |`,
    `| صفوف العروات الإضافية | ${r.stats.extraRows} |`,
    `| الأصناف المستوردة | ${r.stats.crops} |`,
    `| مواعيد زراعة أساسية مستوردة | ${r.stats.plantingWindows} |`,
    `| عروات إضافية اختيارية مستوردة | ${r.stats.optionalWindows} |`,
    `| مناطق «غير ملائم غالبًا» (قيد، لا موعد) | ${r.stats.notRecommendedZones} |`,
    `| مواسم إزهار وقطف مستوردة | ${r.stats.phaseWindows} |`,
    `| قيم مستبعدة | ${excluded.length} |`,
    `| ملاحظات (استُوردت مع تنبيه) | ${warnings.length} |`,
    "",
    "## القيم المستبعدة وأسبابها",
    "",
    excluded.length ? "| الملف | الصنف | المنطقة | ما استُبعد والسبب |\n| --- | --- | --- | --- |\n" + excluded.map(row).join("\n") : "لا توجد قيم مستبعدة.",
    "",
    "## ملاحظات آلية",
    "",
    warnings.length ? "| الملف | الصنف | المنطقة | الملاحظة |\n| --- | --- | --- | --- |\n" + warnings.map(row).join("\n") : "لا توجد ملاحظات.",
    "",
    "## مراجعة زراعية يدوية",
    "",
    ...(REVIEW_NOTES[dataset] ?? []).map((n) => `- **${names.get(n.slug) ?? n.slug}**: ${n.note}`),
    "",
    "## كيف تُعرض هذه البيانات",
    "",
    "- كل موعد مستورد حالته `estimated`، ولا يحمل حالة موثّق أو مراجَع. الأصناف التي ليس لها إلا تقديرات حالتها «مواعيد تقديرية».",
    "- المواعيد مقيّدة بفلسطين (`PS`) وبمنطقتها المناخية، ولا تظهر لموقع في دولة أخرى أو لموقع لم يُعرف بلده.",
    "- الموعد الموثّق يتقدّم دائمًا على التقدير؛ يُستعمل التقدير فقط حيث لا يوجد موعد موثّق للمنطقة.",
    "- العروات الإضافية تظهر في صفحة النبات فقط، ولا تدخل في «ماذا أزرع الآن؟».",
    "- الروابط في الملف مراجع سياقية عامة، ولا تثبت كل موعد.",
    "",
  ];
  return out.join("\n");
}

const outputs: [string, string][] = [
  [paths.out, moduleSource(result)],
  [paths.report, reportSource(result)],
];
if (check) {
  const stale = outputs.filter(([p, src]) => {
    try {
      return readFileSync(join(root, p), "utf8") !== src;
    } catch {
      return true;
    }
  });
  if (stale.length) {
    console.error(`ملفات غير محدثة: ${stale.map(([p]) => p).join("، ")}. شغّل npm run estimates:import`);
    process.exit(1);
  }
  console.log("الملفات المولّدة محدثة.");
} else {
  for (const [p, src] of outputs) writeFileSync(join(root, p), src, "utf8");
  console.log(`استُورد ${result.stats.crops} صنفًا: ${result.stats.plantingWindows} موعد زراعة، ${result.stats.optionalWindows} عروة إضافية، ${result.issues.filter((i) => i.level === "excluded").length} قيمة مستبعدة.`);
}
